        // texte du code (francais + anglais) dans la langue lang
        public static string Tr(int lang, string fr, string en)
        {
            if (lang == 1) return fr;
            if (lang < 0 || lang >= Col.Length || Col[lang] < 0 || en == null) return en;
            string[] t;
            if (P.TryGetValue(en, out t) && Col[lang] < t.Length && t[Col[lang]].Length > 0) return t[Col[lang]];
            return en;
        }

        // texte connu seulement en francais (noms du catalogue, des rangs, des courses...)
        public static string TrFr(int lang, string fr)
        {
            string en;
            if (fr == null || !FrToEn.TryGetValue(fr, out en)) return fr;
            return Tr(lang, fr, en);
        }

        // textes de la fenetre du programme (ecrits en francais)
        public static string Win(int lang, string fr)
        {
            if (lang == 1 || fr == null) return fr;
            string en;
            if (!WinEn.TryGetValue(fr, out en) || en.Length == 0) en = fr;
            if (lang < 0 || lang >= Col.Length || Col[lang] < 0) return en;
            string[] t;
            if (W.TryGetValue(fr, out t) && Col[lang] < t.Length && t[Col[lang]].Length > 0) return t[Col[lang]];
            return en;
        }

        // langue de Windows -> numero de langue du jeu
        public static int FromCulture()
        {
            CultureInfo ci = CultureInfo.CurrentUICulture;
            string two = ci.TwoLetterISOLanguageName.ToLowerInvariant();
            switch (two)
            {
                case "fr": return 1;
                case "de": return 2;
                case "es": return 3;
                case "it": return 4;
                case "ja": return 6;
                case "ko": return 7;
                case "ru": return 8;
                case "pt": return ci.Name.EndsWith("BR", StringComparison.OrdinalIgnoreCase) ? 16 : 9;
                case "nl": return 10;
                case "fi": return 12;
                case "sv": return 13;
                case "da": return 14;
                case "nb": case "nn": case "no": return 15;
                case "hu": return 17;
                case "ca": return 18;
                case "is": return 19;
                case "pl": return 20;
                case "lt": return 21;
                case "cs": return 22;
                case "hr": return 23;
                case "gl": return 24;
            }
            return 0;
        }
    }
